# positions of 5 and zeros
five=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5]
minr=min(r for r,c in five); minc=min(c for r,c in five)
shape=[(r-minr,c-minc) for r,c in five]
H,W=len(grid),len(grid[0]); print(shape, len(five))
matches=[]
for r in range(H-max(x for x,y in shape)):
 for c in range(W-max(y for x,y in shape)):
  if all(grid[r+dr][c+dc]==0 for dr,dc in shape): matches.append((r,c))
print(matches)
